local E = ns.DB.entries
E["item:grimtotem-satchel"] = {t="item",n="Grimtotem Satchel",z="ragefire",s="The Grimtotem Satchel is a leather pouch clutched by the fallen tauren Maur Grimtotem deep inside Ragefire Chasm. Even as troggs overwhelmed him in the subterranean cavern beneath Orgrimmar, Maur shielded this pack with his dying breath. Recovering it and returning it to Thunder Bluff reveals that Elder Crone Magatha Grimtotem had an active interest in whatever her clansman carried.",h="The Grimtotem Satchel is a leather pouch clutched by the fallen tauren Maur Grimtotem deep inside Ragefire...",sec={{t="A Dying Grip",b="Discovered beneath the broken body of Maur Grimtotem in the depths of Ragefire Chasm, this simple pack was held in a fierce, vice-like embrace. Maur fought desperately to protect whatever it contains while surrounded and slain by savage troggs. The sheer determination required to shield a satchel above one's own life suggests its contents are far more significant than ordinary trail rations or supplies.",sp=0},{t="The Elder Crone's Interest",b="Upon carrying the satchel to Rahauro on the Elder Rise in Thunder Bluff, the greater mystery unfurls. Rahauro accepts the pack on behalf of Magatha Grimtotem, the matriarch of the Grimtotem clan. Maur was Magatha's servant, and word had reached her that he found something peculiar in the caverns below Orgrimmar before he died; Magatha specifically arranged rewards for its safe return, demonstrating that the Grimtotem leadership had deliberate, covert stakes in the trogg-infested chasm.",sp=1}},faq={{q="Where is the Grimtotem Satchel found?",a="The satchel is discovered deep inside Ragefire Chasm, the volcanic cavern beneath Orgrimmar. It lies tucked under the corpse of Maur Grimtotem, pinned in his arms where he fell to the cavern's troggs.",al={"satchel location","where is the satchel","how to find satchel"},it="place",gp=true},{q="Who does the satchel belong to?",a="It belonged to Maur Grimtotem, a member of the Grimtotem clan who ventured into Ragefire Chasm. Even in death, his arms remained tightly wrapped around the pack to protect its contents from the attacking troggs.",al={"who owns the satchel","maur satchel owner"},it="identity"},{q="Who wants the satchel returned?",a="The satchel is delivered to Rahauro on the Elder Rise in Thunder Bluff. Rahauro accepts it under the direct orders of Magatha Grimtotem, who arranged a reward for anyone who recovered her fallen clansman's belongings.",al={"who gets the satchel","who turns in satchel","who wants grimtotem satchel"},it="why_wanted"},{q="Why was a Grimtotem carrying this under Orgrimmar?",a="Maur Grimtotem was a servant of Magatha Grimtotem, who had taken an interest in Ragefire Chasm. He went into the chasm to speak with the troggs and found something peculiar there, but he never made it out to show her what.",al={"why was maur in ragefire","what was the grimtotem doing in orgrimmar"},it="motive"},{q="What is inside the satchel?",a="The exact contents inside the pouch are kept sealed and are handed directly to Rahauro in Thunder Bluff. Magatha hopes it holds signs of the peculiar thing Maur found in the chasm.",al={"satchel contents","what is in the bag"},it="item"}},ang={["race:Tauren"]="Finding a Grimtotem operating deep beneath Orgrimmar and reporting back to Magatha on the Elder Rise highlights the subtle, uneasy political maneuvers of the Grimtotem within the united tauren tribes.",["faction:Horde"]="The discovery of a dead Grimtotem courier deep in the tunnels beneath Thrall's capital shows that the perils of Ragefire Chasm extend far beyond simple beast infestations."},kw={"elder rise","grimtotem","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","satchel","thunder bluff","trogg"},rel={"quest:5724","npc:maur-grimtotem","npc:rahauro","zone:ragefire","zone:thunderbluff","subzone:elder-rise","topic:tauren","topic:trogg"},src={"Grimtotem Satchel","Returning the Lost Satchel"}}
E["item:incantations-from-the-nether"] = {t="item",n="Incantations from the Nether",z="ragefire",s="Incantations from the Nether is a grimoire of demonic magic held by the Searing Blade cultists lurking beneath Orgrimmar. Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, seek to claim the tome to harness its fel knowledge for the Forsaken.",h="Incantations from the Nether is a grimoire of demonic magic held by the Searing Blade cultists lurking...",sec={{t="Gifts of the Legion",b="Beneath the red stone streets of Orgrimmar, the Searing Blade—a subterranean sect tied to the Shadow Council—operates in the fiery tunnels of Ragefire Chasm. Among their darkest treasures is the Incantations from the Nether, a spellbook laden with demonic rites bestowed by agents of the Burning Legion. While the cultists use its vile secrets to plot treason within the Orcish capital, word of the text reached far across the sea to the royal quarters of Undercity.",sp=0},{t="Forsaken Ambition",b="To Lady Sylvanas Windrunner and the dreadlord Varimathras, such powerful fel relics are wasted on cultists with what they view as lesser vision. Varimathras dispatches loyal Horde adventurers deep into Ragefire Chasm to recover the Incantations alongside its sister volume, Spells of Shadow. The Dark Lady intends to bend the nether-forged powers of the book toward her ultimate crusade: destroying the Lich King and delivering retribution to the Scourge.",sp=1}},faq={{q="Where is the book Incantations from the Nether found?",a="The book is carried by the Searing Blade cultists and warlocks who lurk in Ragefire Chasm, the volcanic cavern network directly underneath the city of Orgrimmar.",al={"where to get incantations from the nether","who drops incantations from the nether","incantations from the nether location"},it="place",gp=true},{q="Who wants this book and why?",a="The dreadlord Varimathras and Lady Sylvanas Windrunner seek the book. They believe demonic gifts like these are wasted on the petty cultists of the Searing Blade and wish to turn its dark magic against their sworn enemy, the Lich King.",al={"who needs incantations from the nether","why does sylvanas want this book","varimathras book quest"},it="why_wanted"},{q="What is the Searing Blade?",a="The Searing Blade is a secretive coven of warlocks and cultists operating beneath Orgrimmar, allied with the Shadow Council. They serve the Burning Legion and work from the shadows to undermine Thrall's new Horde.",al={"searing blade lore","who are the searing blade"}},{q="What other book is paired with this one?",a="Varimathras requires two volumes: Incantations from the Nether and a second grimoire called Spells of Shadow. Both must be wrested from the cultists in Ragefire Chasm to complete his mission.",al={"other book for varimathras","power to destroy books"},it="item"},{q="What is Incantations from the Nether?",a="Incantations from the Nether is a dark grimoire containing fel spellcraft gifted by the Burning Legion. It came into the possession of the Searing Blade, a hidden cult of the Shadow Council operating deep within the fiery chasms beneath Orgrimmar. Alongside its sister tome, Spells of Shadow, the book holds potent demonic rituals that cultist warlocks study to harness the powers of the Twisting Nether.",al={"what is incantations from the nether","incantations from the nether book","what kind of book is incantations from the nether"},it="identity",add=true}},ang={["race:Undead"]="Recovering this book directly aids the Dark Lady's inner circle in Undercity, gathering dark knowledge needed to wage war against the Scourge.",["class:Warlock"]="Tomes drawn directly from the Nether contain potent fel magic that any ambitious practitioner of the dark arts would covet."},kw={"incantations from the nether","ragefire chasm","searing blade","shadow council","spells of shadow","sylvanas","the power to destroy","varimathras"},rel={"quest:5725","item:spells-of-shadow","npc:varimathras","zone:ragefire","topic:forsaken","topic:shadow-council","zone:undercity","zone:orgrimmar"},src={"Incantations from the Nether","The Power to Destroy... (Classic)"}}
E["item:spells-of-shadow"] = {t="item",n="Spells of Shadow",z="ragefire",s="Spells of Shadow is a dark grimoire carried by the Searing Blade cultists lurking beneath Orgrimmar in Ragefire Chasm. Filled with fel magic granted by the Burning Legion, it is targeted for recovery by the Forsaken leadership in the Undercity.",h="Spells of Shadow is a dark grimoire carried by the Searing Blade cultists lurking beneath Orgrimmar in...",sec={{t="Tomes of the Searing Blade",b="Hidden deep in the molten caverns of Ragefire Chasm, members of the Searing Blade—a splinter cult tied to the Shadow Council—wield dark rites granted by demon masters of the Burning Legion. Among their most guarded treasures is the Spells of Shadow, a text containing insidious shadow and fel sorcery. Cultists and warlocks of the sect keep this book close at hand as they plot beneath the very feet of the Horde in Durotar.",sp=0},{t="The Dark Lady's Ambition",b="Word of the Searing Blade's demonic gifts reached the royal quarters of the Undercity. Lady Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, determined that such powerful relics were wasted on cultists with lesser vision. Varimathras tasks Horde adventurers with venturing into the chasm to seize the Spells of Shadow alongside its companion tome, Incantations from the Nether, directing their power toward the Forsaken cause against the Scourge and the Lich King.",sp=0}},faq={{q="What is the Spells of Shadow?",a="It is a demonic spellbook possessed by the Searing Blade cultists in Ragefire Chasm, containing gifts of shadow magic bestowed by the Burning Legion.",al={"spells of shadow book","what is spells of shadow","shadow spells book rfc"},it="identity"},{q="Who wants this book?",a="Varimathras, the dreadlord advisor to Lady Sylvanas Windrunner, seeks the tome on behalf of the Dark Lady. He resides in the Royal Quarter of the Undercity.",al={"who needs spells of shadow","who turns in spells of shadow","spells of shadow quest giver"},it="why_wanted"},{q="Where can the book be found?",a="It is carried by Searing Blade cultists and warlocks inside Ragefire Chasm, the network of fiery caverns located underneath the city of Orgrimmar.",al={"spells of shadow location","where to get spells of shadow","how to get spells of shadow"},it="place",gp=true},{q="Why do the Forsaken want this grimoire?",a="Lady Sylvanas believes the dark gifts granted by the Legion are better utilized by the Forsaken than by lesser cultists, using such magic to bolster her war against the Scourge and the Lich King.",al={"why does sylvanas want the book","why does varimathras want spells of shadow"},it="why_wanted"}},ang={["race:Undead"]="Retrieving the grimoire serves Lady Sylvanas directly, claiming dangerous demonic knowledge beneath Orgrimmar to strengthen the Undercity against the Scourge.",["class:Warlock"]="The tome represents direct demonic patronage from the Legion, showcasing how rogue cults like the Searing Blade wield shadow and nether arts."},kw={"incantations from the nether","ragefire chasm","searing blade","spells of shadow","sylvanas","the power to destroy","undercity","varimathras"},rel={"quest:5725","item:incantations-from-the-nether","zone:ragefire","npc:varimathras","zone:undercity","topic:shadow-council","topic:forsaken","zone:orgrimmar"},src={"Spells of Shadow","The Power to Destroy... (Classic)"}}
E["item:taragaman-the-hungerer-s-heart"] = {t="item",n="Taragaman the Hungerer's Heart",z="ragefire",s="Taragaman the Hungerer's Heart is the grisly trophy taken from the felguard presiding over the depths of Ragefire Chasm. Neeru Fireblade requests this foul organ as proof that the demonic presence beneath Orgrimmar has been purged.",h="Taragaman the Hungerer's Heart is the grisly trophy taken from the felguard presiding over the depths of...",sec={{t="A Trophy of Deceit",b="Carved from the chest of Taragaman the Hungerer, this steaming demonic heart serves as physical proof of the brute's demise. Neeru Fireblade claims to Thrall and eager adventurers alike that Taragaman is the mastermind behind the Searing Blade cultists lurking in Ragefire Chasm. Presenting the heart to Neeru ostensibly satisfies the Warchief's mandate to safeguard Orgrimmar from demonic corruption, though presenting a brutish felguard as the cult's true architect conveniently conceals the deeper mortal networks operating beneath the city.",sp=1}},faq={{q="Who wants Taragaman the Hungerer's Heart?",a="Neeru Fireblade, an orc warlock residing in the Cleft of Shadows within Orgrimmar, asks adventurers to bring him the heart as proof that the demon has been slain.",al={"who takes taragaman heart","taragaman heart turn in","who wants the heart"},it="why_wanted"},{q="Where do I obtain this heart?",a="The heart is looted directly from the corpse of Taragaman the Hungerer, an imposing felguard located in the central magma chambers of Ragefire Chasm beneath Orgrimmar.",al={"how to get taragaman heart","where does taragaman heart drop","taragaman heart location"},it="origin",gp=true},{q="Does Thrall ever see the heart?",a="No. You deliver the heart directly to Neeru Fireblade, who claims he will properly handle the demonic remains and inform Warchief Thrall of the victory on your behalf.",al={"does thrall get the heart","give heart to thrall","thrall taragaman heart"}},{q="Was Taragaman truly the leader of the Searing Blade?",a="Neeru Fireblade names the felguard as the Searing Blade's leader and insists that slaying him and bringing back his heart will appease Thrall.",al={"is taragaman the leader","who leads searing blade","taragaman real boss"},sp=1},{q="What is Taragaman the Hungerer's Heart?",a="It is the severed heart of Taragaman the Hungerer, a massive felguard lurking in the fiery depths of Ragefire Chasm beneath Orgrimmar. Carried out of the caverns by adventurers, it serves as physical proof that the monstrous demon commanding the Searing Blade's demonic forces in the chasm has been struck down.",al={"what is taragaman heart","taragaman the hungerer heart","taragaman heart lore"},it="identity",add=true},{q="Where does Taragaman the Hungerer's Heart come from?",a="The heart is carved from the chest of Taragaman the Hungerer, an enormous felguard stationed deep within Ragefire Chasm. Taragaman was summoned and harbored in the subterranean tunnels beneath Orgrimmar by the Searing Blade cultists, making the heart an organic relic of the demonic corruption infesting the city's underbelly.",al={"taragaman heart origin","where did the heart come from","who made taragaman heart"},it="origin",add=true}},ang={["faction:Horde"]="Cleansing the tunnels beneath Orgrimmar protects the young capital from being corrupted from within, making the beast's severed heart a symbol of the Horde's vigilance.",["class:Warlock"]="Dealing with Neeru Fireblade and handling harvested demonic remnants is familiar territory for warlocks, who understand the delicate web of shadow and deception playing out in the Cleft of Shadows."},kw={"felguard","heart","hungerer","neeru fireblade","orgrimmar","ragefire chasm","searing blade","taragaman"},rel={"npc:taragaman-the-hungerer","quest:5761","quest:829","zone:ragefire","zone:orgrimmar","quest:5726","npc:thrall","topic:horde"},src={"Taragaman the Hungerer's Heart","Slaying the Beast (quest)"}}
E["npc:bazzalan"] = {t="npc",n="Bazzalan",z="ragefire",s="Bazzalan is a sinister satyr rogue lurking within the volcanic depths of Ragefire Chasm. Alongside Jergosh the Invoker, he commands the dark activities of the Searing Blade cult directly beneath the Horde capital of Orgrimmar.",h="Bazzalan is a sinister satyr rogue lurking within the volcanic depths of Ragefire Chasm.",sec={{t="A Serpent Beneath the City",b="While Thrall works to establish the Orcs' new home across Durotar, ancient evils have found a roost beneath his feet. Bazzalan, a cunning satyr rogue, has allied with the Searing Blade cult inside the winding lava caverns of Ragefire Chasm. Swift and lethal with twin blades, he serves as one of the cult's primary field commanders.",sp=0},{t="Cult Leadership and Deceit",b="Perched upon a dark volcanic ledge overlooking the central chamber where Jergosh the Invoker conducts demonic rituals, Bazzalan oversees his cultist guards. Like all satyrs, his ultimate loyalty lies with demonic masters, using poisons, fast strikes, and dark stealth to eliminate any Horde scouts who venture too close to the cult's staging ground.",sp=0}},faq={{q="Who is Bazzalan?",a="Bazzalan is a satyr rogue and co-leader of the Searing Blade cult operating inside Ragefire Chasm beneath Orgrimmar.",al={"bazzalan lore","who is bazzalan","satyr boss rfc"},it="identity"},{q="Where can Bazzalan be found in Ragefire Chasm?",a="He lurks along the upper ledges of Ragefire Chasm, stationed above Jergosh the Invoker. He can be reached by climbing dark ramps cut into the cavern walls.",al={"bazzalan location","where is bazzalan","find bazzalan"},it="place",gp=true},{q="What is a satyr doing beneath Orgrimmar?",a="Bazzalan works in concert with the Searing Blade, a demonic cult seeking to undermine the Horde from within. Satyrs are bound to demonic powers and frequently act as instigators and assassins for shadow councils.",al={"why is there a satyr in orgrimmar","why is bazzalan in rfc"},it="why_here"},{q="What abilities does Bazzalan use in combat?",a="Bazzalan fights as a classic rogue, striking rapidly with melee weapons, using Sinister Strike, and occasionally afflicting opponents with a mild debilitating poison.",al={"bazzalan abilities","bazzalan attacks","how does bazzalan fight"},it="power",gp=true},{q="What is his relationship to Jergosh the Invoker?",a="Bazzalan and Jergosh share leadership of the Searing Blade inside Ragefire Chasm. While Jergosh focuses on invocations and summoning dark forces, Bazzalan acts as the martial and stealth authority.",al={"jergosh and bazzalan","is bazzalan related to jergosh"},it="ties"},{q="Why does the Horde want Bazzalan dead?",a="His presence deep beneath the capital represents a direct demonic threat. Horde leaders commission adventurers to infiltrate Ragefire Chasm and eliminate him before the Searing Blade's plot endangers the city.",al={"bazzalan bounty","repel the invasion bazzalan"},it="motive"},{q="Whose side is Bazzalan on?",a="Bazzalan serves the demonic masters behind the Shadow Council. Operating directly alongside Jergosh the Invoker, he commands the Searing Blade cultists lurking beneath Orgrimmar, working in secret against the Horde and the safety of the city above.",al={"who does bazzalan serve","bazzalan faction","bazzalan allegiance"},it="side",add=true}},ang={["faction:Horde"]="Bazzalan and his cult pose an intolerable hazard right below Thrall's stronghold, necessitating immediate extermination.",["class:Rogue"]="Bazzalan displays classic stealth techniques, vicious strikes, and venom-coated blades, making him an opponent of distinct professional interest.",["race:Orc"]="Having fought so hard to escape the clutches of demonic manipulation, Orcs view a satyr directing cultists in their own foundations as an outrage."},kw={"bazzalan","cultist","jergosh","orgrimmar","ragefire chasm","rfc","satyr","searing blade"},rel={"zone:ragefire","npc:jergosh-the-invoker","topic:satyr"},src={"Bazzalan"}}
E["npc:jergosh-the-invoker"] = {t="npc",n="Jergosh the Invoker",z="ragefire",s="Jergosh the Invoker is a treacherous orc warlock hiding deep within Ragefire Chasm beneath Orgrimmar. As a high-ranking leader among the Searing Blade cultists, he practices demonic arts directly under the Warchief's nose and plots against the Horde.",h="Jergosh the Invoker is a treacherous orc warlock hiding deep within Ragefire Chasm beneath Orgrimmar.",sec={{t="A Cult Beneath the City",b="While Thrall works tirelessly to lead the orcs along a path of honor and shamanism, Jergosh rejected these ideals in favor of raw demonic power. Concealing himself within the subterranean labyrinth of Ragefire Chasm beneath Orgrimmar, he gathered followers into the Searing Blade, an insidious sect aligned with the remnants of the Shadow Council. Operating in the shadows directly below the Horde capital, Jergosh works to undo everything the new Horde stands for.",sp=0},{t="Demonic Ambitions",b="Jergosh's presence in the chasm is far from aimless wandering. His dark rituals and dangerous schemes eventually grew bold enough to attract the direct scrutiny of Thrall himself. Among his sinister possessions is the Blood Filled Orb, a potent artifact tied to the summoning of demonic terrors such as Zelemar the Wrathful. Jergosh represents an existential infection within Durotar, reminding the Horde of the dark pacts they fought so desperately to leave behind.",sp=1}},faq={{q="Who is Jergosh the Invoker?",a="Jergosh the Invoker is a powerful orc warlock and a leader of the Searing Blade cultists operating within Ragefire Chasm. Rather than following Thrall's honorable path, he chose to embrace demonic sorcery.",al={"who is jergosh","jergosh lore","jergosh ragefire"},it="identity"},{q="Why is Jergosh hiding in Ragefire Chasm?",a="Ragefire Chasm provides the Searing Blade with a secluded network of fiery caverns directly beneath Orgrimmar. From there, Jergosh and his cultists can practice forbidden dark magic and conspire against the Horde undetected.",al={"why is jergosh under orgrimmar","jergosh location lore"},it="why_here"},{q="What faction does Jergosh belong to?",a="Jergosh is a leader within the Searing Blade, a cult linked to the Shadow Council and devoted to serving demonic interests like the Burning Legion.",al={"jergosh faction","is jergosh shadow council","searing blade leader"},it="side"},{q="Does Thrall know Jergosh is beneath Orgrimmar?",a="Yes. Jergosh's plots grew dangerous enough that rumors reached Thrall, leading the Warchief to dispatch trusted adventurers into the chasm to eliminate the cultist menace.",al={"thrall jergosh","does thrall know about ragefire"}},{q="What is the Blood Filled Orb Jergosh guards?",a="The Blood Filled Orb is a dark ritual focus held by Jergosh. Warlocks undertaking specific trials can use it to summon the demon Zelemar the Wrathful.",al={"blood filled orb","zelemar summoning orb"},it="item"},{q="Why does Jergosh practice fel magic instead of shamanism?",a="Jergosh willingly turned his back on the spiritual resurgence of his people, rejecting shamanistic harmony to chase the intoxicating power promised by the Burning Legion and dark arts.",al={"why warlock","jergosh fel magic"}},{q="What does Jergosh the Invoker want?",a="Jergosh aims to undermine the Horde from within its own capital. Rejecting Thrall's renewed shamanistic ideals, he seeks to revive dark demonic practices and further the nefarious ambitions of the Shadow Council. Lurking in the chasm, he concocts subversive schemes dangerous enough to threaten the stability of Orgrimmar itself.",al={"jergosh goal","what does jergosh want","jergosh motive"},it="wants",add=true},{q="Who is Jergosh the Invoker tied to?",a="Jergosh is a prominent leader among the Searing Blade cultists, a subterranean coven operating right beneath Orgrimmar. The cult is secretly an arm of the wider Shadow Council, binding Jergosh directly to the shadowy network of warlocks and demon worshipers seeking to pull the orcish people back into corruption.",al={"jergosh allies","who does jergosh work for","jergosh shadow council"},it="ties",add=true},{q="Why is Jergosh the Invoker feared?",a="Jergosh is feared because he wields forbidden fel magic right beneath the feet of the Horde's leadership. His dark rituals, demonic summoning, and radical rejection of the new Horde's path pose an existential internal threat, drawing the direct attention and concern of Warchief Thrall himself.",al={"why is jergosh feared","is jergosh dangerous","jergosh reputation"},it="fame",add=true}},ang={["race:Orc"]="Jergosh represents the lingering poison of the old Horde—the temptation of demonic blood and sorcery that Thrall strives to purge from orcish culture.",["class:Warlock"]="For warlocks, Jergosh is both a dark mentor figure to surpass and the guardian of the Blood Filled Orb needed to summon Zelemar the Wrathful.",["faction:Horde"]="Having a Shadow Council cell thriving beneath the chieftain's throne room is an intolerable security threat that the Horde cannot afford to ignore."},kw={"blood filled orb","invoker","jergosh","orgrimmar","ragefire chasm","searing blade","shadow council","warlock","zelemar"},rel={"zone:ragefire","topic:shadow-council","npc:thrall","topic:burning-legion"},src={"Jergosh the Invoker"}}
E["npc:maur-grimtotem"] = {t="npc",n="Maur Grimtotem",z="ragefire",s="Maur Grimtotem was an emissary sent by Elder Crone Magatha Grimtotem into the depths of Ragefire Chasm. Dispatched on an ill-fated diplomatic mission to the troggs infesting the subterranean tunnels beneath Orgrimmar, he met a brutal end at their hands. Today, only his remains and personal satchel linger in the dark as evidence of the foolish errand.",h="Maur Grimtotem was an emissary sent by Elder Crone Magatha Grimtotem into the depths of Ragefire Chasm.",sec={{t="A Doomed Diplomacy",b="While most in the Horde view troggs as mindless, savage brutes beneath negotiation, Elder Crone Magatha Grimtotem thought otherwise—or at least claimed to. She dispatched Maur Grimtotem deep into the winding caverns of Ragefire Chasm beneath Orgrimmar to attempt a peaceful overture with the subterranean beasts. Predictably, diplomacy failed. Maur was swiftly slain, his corpse left in the caverns under the watchful eye of the trogg chieftain Oggleflint.",sp=0},{t="The Elder Crone's Interests",b="Following Maur's demise, Magatha sought adventurers not merely to avenge him, but to retrieve the personal satchel he carried into the depths. Whether Maur genuinely believed peace with troggs was possible or was merely an expendable pawn in the Grimtotem matriarch's shadowy schemes remains an open question to those who recover his belongings.",sp=1}},faq={{q="Who was Maur Grimtotem?",a="Maur was a tauren belonging to the Grimtotem clan. Acting on the orders of Magatha Grimtotem, he ventured into the caverns of Ragefire Chasm beneath Orgrimmar as an emissary to the troggs, where he was killed.",al={"who is maur","maur grimtotem lore","what was maur doing"},it="identity"},{q="Why did he try to negotiate with troggs?",a="Elder Crone Magatha claimed she sent him to seek peace and test the strength of these subterranean foes. Given the troggs' feral nature, many suspect Magatha had ulterior motives or simply used Maur to probe Ragefire Chasm's depths.",al={"why make peace with troggs","trogg diplomacy","why talk to troggs"},it="why_here"},{q="Who killed Maur Grimtotem?",a="Maur was slain by the trogg tribe living in Ragefire Chasm. His corpse was found guarded closely by Oggleflint, the chieftain of the Ragefire troggs.",al={"how did maur die","who killed him","maur death"},it="threat"},{q="What happened to his body and belongings?",a="Maur's body was abandoned in Ragefire Chasm near Oggleflint. Adventurers are tasked by Rahauro in Thunder Bluff to recover Maur's lost satchel and bring it back to Magatha Grimtotem on the Elder Rise.",al={"maur corpse","lost satchel","maur's satchel"}},{q="Whose side was Maur Grimtotem on?",a="Maur answered directly to Elder Crone Magatha Grimtotem and served the interests of the Grimtotem clan. While the Grimtotem are technically counted among the Horde through their uneasy presence on Thunder Bluff's Elder Rise, Maur's loyalties and secret mission belonged solely to his clan.",al={"maur grimtotem faction","who does maur grimtotem serve","maur grimtotem alliance horde"},it="side",add=true},{q="What did Maur Grimtotem want?",a="Maur sought to forge an alliance or peaceful accord with the troggs infesting the chasms beneath Orgrimmar. Following Magatha Grimtotem's instructions, he ventured into Ragefire Chasm hoping to negotiate with the creatures, unaware that their feral and violent nature made any diplomatic understanding impossible.",al={"what was maur grimtotem doing","maur grimtotem mission","maur grimtotem goal"},it="wants",add=true},{q="Who was Maur Grimtotem tied to?",a="Maur was an emissary sent by Magatha Grimtotem, the matriarch of the Grimtotem clan who currently resides on Thunder Bluff's Elder Rise. He carried out her private designs below Orgrimmar, keeping his mission separate from the standard Horde leadership.",al={"who sent maur grimtotem","maur grimtotem connections","maur grimtotem magatha"},it="ties",add=true}},ang={["race:Tauren"]="The Grimtotem clan has an uneasy relationship with the rest of the tribes in Thunder Bluff, and Maur's bizarre, fatal errand into trogg tunnels only deepens suspicion about Magatha's true agenda.",["faction:Horde"]="Having a deadly subterranean cavern right under Orgrimmar is bad enough; sending solitary envoys to negotiate with troggs proved entirely disastrous for the Horde's safety."},kw={"grimtotem","magatha","maur","oggleflint","orgrimmar","ragefire","satchel","trogg"},rel={"npc:magatha-grimtotem","npc:oggleflint","zone:ragefire","quest:5722","quest:5724","quest:5723","topic:trogg","topic:tauren"},src={"Maur Grimtotem"}}
E["npc:oggleflint"] = {t="npc",n="Oggleflint",z="ragefire",s="Oggleflint is the chieftain of the trogg tribe dwelling within the volcanic depths of Ragefire Chasm directly beneath Orgrimmar. Once master of the entire subterranean cavern, he and his kin have been pushed toward the upper tunnels by the arrival of the Searing Blade cultists. Now entrenched near the entrance, he commands his savage pack and poses an immediate threat to the Horde capital above.",h="Oggleflint is the chieftain of the trogg tribe dwelling within the volcanic depths of Ragefire Chasm directly...",sec={{t="Chieftain of the Deep",b="Before shadow cultists infiltrated the chasm beneath Orgrimmar, Oggleflint and his troggs ruled the fiery subterranean tunnels uncontested. Brutal and territorial, they carved out a primitive domain among the molten rock. Though troggs possess little in the way of advanced civilization, Oggleflint maintained absolute authority over the pack through sheer brute strength.",sp=0},{t="Displaced by the Cult",b="The balance of power beneath the city shattered when the Searing Blade moved into the deepest chambers of Ragefire Chasm. Unable to match the dark magic and coordinated zealots of the cult, Oggleflint was forced to cede the lower tunnels. Retreating upward, the trogg chieftain now waits near the cavern entrance, striking at any outsiders while nursing grudges against the interlopers below.",sp=0},{t="The Threat Beneath Orgrimmar",b="Having displaced troggs directly beneath Thrall's capital is a hazard the Horde cannot tolerate. Pushed closer to the surface, Oggleflint's tribe is far too volatile to leave unchecked, threatening to spill into the Drag and Cleft of Shadows if left undisturbed.",sp=0}},faq={{q="Who is Oggleflint?",a="Oggleflint is a powerful trogg chieftain who leads the pack inhabiting Ragefire Chasm beneath the city of Orgrimmar.",al={"oggleflint","who is oggleflint","ragefire trogg boss"},it="identity"},{q="Where can Oggleflint be found?",a="He is located in the upper caverns of Ragefire Chasm, not far from the entrance tunnel, where his surviving clan made camp after being pushed out of the deeper reaches.",al={"where is oggleflint","oggleflint location","find oggleflint"},it="place",gp=true},{q="Why are the troggs in Ragefire Chasm?",a="Troggs naturally dwell deep underground in subterranean volcanic networks. Oggleflint's pack claimed the fiery caverns beneath Durotar long before the Searing Blade cult arrived.",al={"why are troggs under orgrimmar","ragefire trogg lore"},it="why_here"},{q="Why is Oggleflint hostile to the Horde?",a="Troggs are fiercely territorial and violent beasts by nature. Pushed toward the surface by cultists, Oggleflint and his followers pose an imminent danger to the Horde tunnels and the city above.",al={"why kill oggleflint","why fight oggleflint"},it="hostile"},{q="What is Oggleflint's relationship with the Searing Blade?",a="They are bitter enemies. The Searing Blade cultists invaded Ragefire Chasm and overpowered Oggleflint's troggs, driving the survivors into the upper caves.",al={"searing blade and oggleflint","are troggs with the cult"},it="conflict"},{q="Whose side is Oggleflint on?",a="Oggleflint fights purely for himself and his trogg brethren. He shares no allegiance with the Horde, the Alliance, or the Shadow Council cultists infesting the chasm. While he once reigned unchecked in the subterranean tunnels beneath Orgrimmar, his followers now skirmish independently against both the Searing Blade intruders and any Horde defenders who descend into the dark.",al={"oggleflint faction","oggleflint alliance or horde","who does oggleflint serve"},it="side",add=true},{q="What does Oggleflint want?",a="Oggleflint wants to reclaim his domain and survive. After the Searing Blade cultists moved into the lower reaches of Ragefire Chasm, his troggs were overpowered and pushed back toward the cavern entrance. Rather than launching a suicidal assault, he waits patiently for the cultists to abandon the caves so his tribe can reoccupy the depths unchallenged.",al={"oggleflint goals","what troggs want ragefire","oggleflint purpose"},it="wants",add=true}},ang={["faction:Horde"]="Living directly beneath Thrall's fortress, Oggleflint's troggs represent a wild, unpredictable security risk right in the heart of Durotar.",["race:Orc"]="For young orcs proving their mettle in the trial of arms, slaying the chieftain lurking right under the Drag is an early test of martial discipline.",["class:Warrior"]="Facing Oggleflint means confronting a heavy brute who relies entirely on raw muscle and primal rage rather than armor or discipline."},kw={"oggleflint","orgrimmar","ragefire chasm","searing blade","trogg"},rel={"zone:ragefire","topic:trogg"},src={"Oggleflint"}}
E["npc:taragaman-the-hungerer"] = {t="npc",n="Taragaman the Hungerer",z="ragefire",s="Taragaman the Hungerer is a hulking felguard lurking within the molten caverns of Ragefire Chasm beneath Orgrimmar. While widely feared as the demonic master behind the Searing Blade cult, his presence in the fiery depths serves a darker, more deceptive purpose. The Horde seeks his destruction to eliminate the demonic taint poisoning the city's underbelly.",h="Taragaman the Hungerer is a hulking felguard lurking within the molten caverns of Ragefire Chasm beneath...",sec={{t="The Beast Below",b="Prowling amidst the magma pools of Ragefire Chasm, Taragaman the Hungerer represents an immediate and terrifying threat to the safety of Orgrimmar. For many scouts and young warriors sent into the dark chasm, the demonic felguard appears to be the central ringleader of the Searing Blade cultists, wielding infernal strength to bend the weak-willed and corrupt the subterranean passages beneath Thrall's fortress.",sp=0},{t="Lethal Decoy",b="Despite his commanding demeanor and devastating brutality, Taragaman is not the mastermind directing the Searing Blade. True leadership of the cult rests in the shadows with the satyr Bazzalan and the warlock Jergosh the Invoker. To these calculating schemers, the towering felguard is little more than expendable bait—a monstrous distraction designed to draw aspiring Horde defenders into the searing volcanic depths where they can be slaughtered.",sp=1}},faq={{q="What kind of demon is Taragaman the Hungerer?",a="Taragaman is a felguard, a brutal demonic shock trooper of the Burning Legion. He wields heavy melee strikes and fiery magic to crush intruders within the magma caverns of Ragefire Chasm.",al={"what race is taragaman","taragaman demon type","is taragaman a demon"},it="identity"},{q="Is Taragaman the Hungerer the leader of the Searing Blade cult?",a="He is widely believed to be. Taragaman is the most fearsome demonic power in Ragefire Chasm, and the Horde's young defenders are sent to slay him as the cult's master, though the chasm may hold more secrets than a single felguard.",al={"who leads searing blade","is taragaman in charge","taragaman cult leader"},it="leader"},{q="Why does the Horde want Taragaman dead?",a="The Horde cannot allow an active demonic presence to fester beneath their capital city. Taragaman's infernal corruption threatens to poison Orgrimmar from within, and eliminating him is vital to securing the cavern passages beneath the streets.",al={"why kill taragaman","slaying the beast quest lore","taragaman orgrimmar threat"},it="motive"},{q="Where can Taragaman be found?",a="Taragaman resides deep within Ragefire Chasm, located in the subterranean volcanic tunnels accessible from the Cleft of Shadow inside Orgrimmar.",al={"taragaman location","where is taragaman","taragaman ragefire chasm"},it="place",gp=true},{q="What happens to Taragaman's heart?",a="Victorious adventurers carve out Taragaman the Hungerer's Heart as proof of the beast's demise to complete the task of clearing out the demonic vanguard festering below Orgrimmar.",al={"taragaman heart","heart of taragaman","slaying the beast heart"},it="item"},{q="How does Taragaman fight in combat?",a="Taragaman relies on devastating physical attacks, a powerful uppercut that knocks foes through the air, and occasional bursts of Fire Nova that scorch anyone standing close to him.",al={"taragaman abilities","taragaman boss fight","taragaman mechanics"},gp=true},{q="Whose side is Taragaman the Hungerer on?",a="Taragaman serves the demonic forces backing the Shadow Council, allied directly with the Searing Blade cultists lurking beneath Orgrimmar. While many believe him to be their master, he actually acts alongside mortal leaders like Bazzalan and Jergosh the Invoker to threaten the Horde from within.",al={"taragaman faction","who does taragaman serve","is taragaman searing blade"},it="side",add=true},{q="Why is Taragaman the Hungerer in Ragefire Chasm?",a="Taragaman dwells within the fiery depths of Ragefire Chasm to spread demonic corruption beneath Orgrimmar. The cult's true leaders also use the hulking felguard as lethal bait, drawing young Horde warriors deep into the caverns to meet their doom.",al={"why is taragaman here","what is taragaman doing in ragefire","why is taragaman in orgrimmar"},it="why_here",add=true},{q="Who is Taragaman the Hungerer tied to?",a="Taragaman is tied to the leaders of the Searing Blade, specifically the satyr Bazzalan and the warlock Jergosh the Invoker. While outsiders mistake the brute for the mastermind behind the cult, the cult's true commanders treat the felguard as expendable muscle and a deadly distraction.",al={"who does taragaman work with","taragaman allies","taragaman bazzalan"},it="ties",add=true},{q="Why is Taragaman the Hungerer feared?",a="Taragaman is feared as a towering demonic terror lurking directly beneath the Horde's capital. His demonic influence threatens to corrupt Orgrimmar's citizens, and his brutal physical might makes him infamous among young defenders sent into the chasm to eliminate him.",al={"why is taragaman famous","is taragaman dangerous","why fear taragaman"},it="fame",add=true}},ang={["faction:Horde"]="For the young warriors and spellcasters of the Horde, slaying Taragaman in the depths beneath Orgrimmar is a critical proving ground to protect their capital from demonic corruption.",["class:Warlock"]="While warlocks practice their dark arts within the Cleft of Shadow above, a wild and hostile felguard like Taragaman poses an untamed danger to the secrecy and safety of their hidden craft.",["class:Warrior"]="Facing Taragaman requires standing firm against crushing physical blows and avoiding being tossed into the surrounding lava by his brutal uppercuts."},kw={"bazzalan","demon","felguard","hungerer","jergosh","orgrimmar","ragefire chasm","searing blade","taragaman"},rel={"quest:5761","zone:ragefire","npc:bazzalan","zone:orgrimmar","topic:horde"},src={"Taragaman the Hungerer"}}
E["quest:5722"] = {t="quest",n="Searching for the Lost Satchel",z="ragefire",s="Searching for the Lost Satchel is a Horde mission offered by Rahauro on the Elder Rise in Thunder Bluff. On behalf of the Elder Crone Magatha Grimtotem, adventurers are directed beneath Orgrimmar into Ragefire Chasm to locate the remains of Maur Grimtotem, an emissary who perished after discovering something unusual among the troggs.",h="Searching for the Lost Satchel is a Horde mission offered by Rahauro on the Elder Rise in Thunder Bluff.",sec={{t="A Grimtotem Mission Beneath Orgrimmar",b="While Warchief Thrall and his advisers concentrate on the Shadow Council presence stirring within Ragefire Chasm, the Grimtotem clan pursues its own discrete interests. Word reaches Magatha Grimtotem on Thunder Bluff's Elder Rise that her emissary, Maur Grimtotem, entered the subterranean cavern beneath Orgrimmar to study and attempt parley with the troggs. Maur never returned, but rumors persist that he made an intriguing discovery shortly before he was killed.",sp=0},{t="The Fallen Emissary",b="Acting on Magatha's behalf, her attendant Rahauro dispatches warriors directly into the chasm. Deep within the lava-filled tunnels, Maur's battered corpse rests near the trogg encampments, violently bludgeoned by crude clubs and bare fists. The beasts ignored his possessions entirely, leaving the tauren's belongings and whatever secrets he sought to recover behind for Magatha's agents to claim.",sp=1}},faq={{q="Who sends adventurers on this quest?",a="Rahauro, an attendant serving Magatha Grimtotem on the Elder Rise of Thunder Bluff, gives out the mission.",al={"quest giver","who starts searching for the lost satchel","where to get quest"},it="identity"},{q="Who is Maur Grimtotem?",a="Maur was an agent of the Grimtotem tribe sent into Ragefire Chasm by Magatha Grimtotem to investigate and attempt communication with the troggs. He was beaten to death in the cavern depths.",al={"maur grimtotem","who was maur","what happened to maur"},it="people"},{q="Why was Magatha Grimtotem interested in Ragefire Chasm?",a="Magatha had an interest in the troggs infesting the tunnels beneath Orgrimmar and sent Maur to attempt communication with them. When Maur found something peculiar among them before dying, she wanted his discovery brought directly to her.",al={"magatha troggs","why magatha cares about ragefire","why send maur"},it="purpose"},{q="Where is Maur Grimtotem's corpse located?",a="Maur's body lies deep within Ragefire Chasm beneath Orgrimmar, lying beaten near the trogg territories along the subterranean paths.",al={"find maur","maur grimtotem location","where is maurs body"},it="place",gp=true},{q="Did the troggs loot Maur after killing him?",a="No. Troggs care little for wealth, tools, or written papers, leaving Maur's garments and satchel undisturbed alongside his broken remains.",al={"trogg loot","was maur robbed"},it="history"},{q="What happens after locating Maur's body?",a="Examining Maur's corpse yields his satchel, prompting the follow-up quest 'Returning the Lost Satchel' to deliver his findings back to Magatha Grimtotem in Thunder Bluff.",al={"follow up quest","next quest after lost satchel","what to do with satchel"},sp=1,it="next_step"},{q="Why does Rahauro want Maur's satchel recovered?",a="Rahauro acts directly on behalf of Elder Magatha Grimtotem. Magatha learned that her servant Maur discovered something unusual deep inside Ragefire Chasm before he met his end attempting to communicate with the troggs. Whatever discovery Maur made never reached Thunder Bluff, and Magatha refuses to let potentially valuable secrets or relics slip away into the dark caverns beneath Orgrimmar.",al={"why does rahauro want this done","rahauro motive","why find maur satchel"},it="motive",add=true},{q="Why does Rahauro send an adventurer instead of Grimtotem braves?",a="Venturing into Ragefire Chasm requires slipping into the fiery underbelly of Orgrimmar, an area crawling with feral troggs and dark cultists far from Thunder Bluff's borders. Sending official Grimtotem warriors or tribal guards into the capital's depths would attract unwanted attention from the orcish authorities. Hiring an able adventurer allows Magatha to discreetly recover Maur's findings without raising suspicions among the Horde leadership.",al={"why send me","why not thunder bluff guards","why an adventurer"},it="why_me",add=true}},ang={["race:Tauren"]="The Grimtotem clan's motives often diverge sharply from Cairne Bloodhoof's open leadership, making Magatha's covert curiosity about subterranean creatures under an allied city worthy of close attention.",["faction:Horde"]="While Thrall focuses on purging dark cultists directly beneath the Horde capital, thunderous whispers from Mulgore reveal that the Grimtotem are pursuing their own quiet goals in the same cavern."},kw={"elder rise","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","searching for the lost satchel","thunder bluff","troggs"},rel={"npc:maur-grimtotem","quest:5724","npc:rahauro","npc:magatha-grimtotem","quest:5723","zone:ragefire","subzone:elder-rise","topic:trogg"},m={start="Rahauro",["end"]="Maur Grimtotem",level="16",faction="Horde",id=5722},src={"Searching for the Lost Satchel"}}
E["quest:5723"] = {t="quest",n="Testing an Enemy's Strength",z="ragefire",s="Testing an Enemy's Strength is a Horde mission assigned by Rahauro on the Elder Rise in Thunder Bluff on behalf of Magatha Grimtotem. After a disastrous diplomatic overture beneath Orgrimmar ended with slaughtered emissaries, the tauren seek retribution by culling the troggs infesting Ragefire Chasm.",h="Testing an Enemy's Strength is a Horde mission assigned by Rahauro on the Elder Rise in Thunder Bluff on...",sec={{t="Diplomacy Meets Savagery",b="When subterranean troggs first emerged from the fiery chasms beneath the orcish capital of Orgrimmar, Elder Crone Magatha Grimtotem made an overture of peace. She dispatched tauren emissaries into the depths to negotiate with the creatures. The response was brutal and immediate: the troggs butchered the delegates without hesitation. Viewing the massacre as an unforgivable insult to the tauren and a gathering danger to the entire Horde, Magatha resolved to answer savagery with decisive force.",sp=0},{t="The Threat Beneath Orgrimmar",b="Operating as Magatha's agent in Thunder Bluff, the tauren Rahauro coordinates the military response. He directs warriors to infiltrate Ragefire Chasm, locate the trogg swarms, and eradicate their frontline warriors and shamans. By striking deep into their subterranean domain, the Horde aims to suppress the trogg population before their subterranean tunnels allow them to pour freely into the streets of Orgrimmar above.",sp=0}},faq={{q="Why is a quest for an Orgrimmar dungeon handed out in Thunder Bluff?",a="The quest originates with the tauren leadership. Magatha Grimtotem personally sent diplomats into Ragefire Chasm to parley with the troggs, and after those delegates were slaughtered, her assistant Rahauro took charge of organizing warriors from the Elder Rise in Thunder Bluff to avenge them.",al={"why thunder bluff","quest start thunder bluff","rahauro location"},it="place"},{q="Who is Rahauro?",a="Rahauro is a tauren questgiver located on the Elder Rise in Thunder Bluff. He acts on behalf of Magatha Grimtotem, coordinating expeditions into Ragefire Chasm to eliminate troggs and recover relics lost during earlier failed diplomatic missions.",al={"who is rahauro","rahauro npc","rahauro elder rise"},it="identity"},{q="Why did Magatha Grimtotem attempt peace with troggs?",a="Magatha intended the initiative as an act of goodwill, attempting to establish relations with the subterranean beings rather than immediately shedding blood. However, the troggs proved incapable of or unwilling to engage in civil discourse, slaughtering her emissaries upon arrival.",al={"why peace with troggs","magatha trogg diplomacy","why negotiate with troggs"},it="conflict"},{q="What enemies need to be slain for this task?",a="You are tasked with entering Ragefire Chasm beneath Orgrimmar and slaying both Ragefire Troggs and Ragefire Shamans to break their front lines and diminish their spellcasting support.",al={"which mobs to kill","quest targets","ragefire troggs"},it="target",gp=true},{q="Can this quest be completed alongside other dungeon tasks?",a="Yes. Rahauro also provides the quest Searching for the Lost Satchel, which sends adventurers into the same chasm to find the remnants of the failed diplomatic party, making it efficient to undertake both simultaneously.",al={"other rfc quests","lost satchel quest","ragefire chasm quests"},gp=true},{q="Where are the troggs coming from?",a="The troggs emerged from deep volcanic fissures beneath Durotar. As Rahauro notes upon the quest's completion, the Horde still knows little about the origins of these savage cave-dwellers or why they have chosen this moment to dig upward into Orgrimmar.",al={"trogg origin rfc","where do troggs come from","why are troggs under orgrimmar"},it="origin"},{q="Why does Rahauro want you to fight the troggs in Ragefire Chasm?",a="Rahauro acts on the orders of Magatha Grimtotem. Magatha initially sought to establish peaceful contact with the troggs emerging beneath Orgrimmar, but the creatures slaughtered her envoys. Refusing to tolerate such an insult and viewing the subterranean beasts as a direct peril to the entire Horde, she sent word through Rahauro to cull their numbers before they overrun the orcish capital.",al={"why kill troggs","rahauro motive","why does magatha want troggs dead"},it="motive",add=true},{q="Who are you being sent to fight in Ragefire Chasm?",a="You are dispatched to hunt down Ragefire troggs and their shaman deep inside the volcanic cleft beneath Orgrimmar. These aggressive, primitive brutes surfaced from subterranean tunnels and violently rejected the tauren's peaceful overtures, murdering Magatha's emissaries and establishing a savage foothold directly beneath the city.",al={"ragefire chasm enemies","who are the troggs","what are we fighting"},it="target",add=true}},ang={["race:Tauren"]="The blood of tauren diplomats stains the stones of Ragefire Chasm, making this assault an act of direct retribution on behalf of the Elder Rise.",["race:Orc"]="Though directed by tauren leadership, this mission directly protects the heart of the orc capital from being overrun by troggs tunneling beneath the city.",["class:Shaman"]="The troggs have their own crude spiritual practitioners who wield primal elements in the lava tunnels, presenting a perverted mirror to honorable shamanistic traditions.",["faction:Horde"]="The mission demonstrates cross-factional solidarity, as Thunder Bluff expends resources and warriors to safeguard the foundations of Orgrimmar."},kw={"elder rise","magatha grimtotem","orgrimmar","ragefire chasm","rahauro","testing an enemy's strength","thunder bluff","troggs"},rel={"npc:rahauro","quest:5722","zone:ragefire","zone:thunderbluff","zone:orgrimmar","topic:trogg","topic:tauren","topic:horde"},m={start="Rahauro",level="15",faction="Horde",id=5723},src={"Testing an Enemy's Strength"}}
E["quest:5724"] = {t="quest",n="Returning the Lost Satchel",z="ragefire",s="This errand concludes the search for Maur Grimtotem deep inside Ragefire Chasm beneath Orgrimmar. Having discovered the slain tauren clinging tightly to his pack, adventurers must carry the recovered satchel back to Rahauro on Elder Rise in Thunder Bluff.",h="This errand concludes the search for Maur Grimtotem deep inside Ragefire Chasm beneath Orgrimmar.",sec={{t="A Grim Discovery",b="Beneath the red rock and fiery depths of Ragefire Chasm, Maur Grimtotem met a brutal end at the hands of the troggs. Even in death, his arms remained locked around his personal satchel, guarding its contents with his final breath. Prying the bag loose from his stiffened grip provides the only clue as to what brought a member of the Grimtotem clan down into the volcanic caverns below Thrall's capital.",sp=0},{t="Magatha's Interest",b="Upon delivering the satchel to Rahauro on Elder Rise, it becomes apparent that the mission was overseen by Magatha Grimtotem herself. Rahauro accepts the package gratefully, seeking answers for why one of Magatha's clan died needlessly, and delivers a reward authorized directly by the Elder Crone. What Maur was carrying—or why Magatha sent him into the trogg-infested fissures of Orgrimmar—remains known only to the leadership of the Grimtotem clan.",sp=1}},faq={{q="Where is Maur Grimtotem located?",a="Maur Grimtotem's corpse lies deep inside the Ragefire Chasm dungeon beneath Orgrimmar, surrounded by hostile troggs.",al={"maur grimtotem corpse","find maur grimtotem","where is maur"},it="place",gp=true},{q="Who do I turn the satchel in to?",a="The Grimtotem Satchel must be brought back to Rahauro, who stands on the Elder Rise in Thunder Bluff.",al={"turn in lost satchel","where is rahauro","satchel turn in"},it="next_step",gp=true},{q="Why was Maur Grimtotem in Ragefire Chasm?",a="Rahauro claims not to know why Magatha's clansman had to die needlessly, but Magatha Grimtotem personally ordered the recovery effort, suggesting Maur was acting on clan business.",al={"why was maur in rfc","maur mission","what was maur doing"},it="why_here"},{q="What is inside the Grimtotem Satchel?",a="The exact contents are never revealed to the courier. Maur protected it fiercely until his death, and it is handed over unopened directly to Rahauro on Magatha's behalf.",al={"what was in the bag","satchel contents"},it="item"},{q="What killed Maur Grimtotem?",a="Maur was ambushed and killed by the savage troggs that infest the tunnels of Ragefire Chasm.",al={"how did maur die","who killed maur"},it="threat"},{q="Who is behind this task?",a="While Rahauro acts as the contact on Elder Rise, the reward and directive come directly from Elder Crone Magatha Grimtotem.",al={"who sent rahauro","magatha connection"},it="leader"},{q="Why does Maur Grimtotem want his satchel returned?",a="Maur Grimtotem did not give you this mission in life—he died clutching his satchel beneath Ragefire Chasm's depths. Even as troggs overwhelmed him, his final act was guarding whatever clan secrets or valuables lay inside. Returning the satchel honors that sacrifice and fulfills the investigation Rahauro and Magatha Grimtotem set in motion to discover what befell their kin.",al={"maur grimtotem motive","why return satchel","why does maur want the satchel returned"},it="motive",add=true},{q="Why were you sent to recover the satchel instead of the Thunder Bluff guards?",a="Ragefire Chasm lies deep beneath the streets of Orgrimmar, far from the jurisdiction of Thunder Bluff's city braves. Entering the subterranean tunnels requires slipping past ferocious troggs and Searing Blade cultists. Rather than causing a diplomatic or military incident by marching Kalimdor forces through an allied capital's depths, Rahauro relied on capable adventurers to quietly track down their fallen clansman.",al={"why me returning lost satchel","why send adventurers ragefire satchel","why don't guards recover satchel"},it="why_me",add=true}},ang={["race:Tauren"]="The Grimtotem clan has an uneasy relationship with Cairne Bloodhoof's people, making any clandestine operation by Magatha's followers in Orgrimmar a cause for suspicion.",["faction:Horde"]="Troggs and cultists threaten the tunnels beneath Orgrimmar, and the covert presence of Grimtotem agents beneath Thrall's fortress raises unanswered political questions."},kw={"elder rise","grimtotem satchel","magatha","maur grimtotem","ragefire chasm","rahauro","returning the lost satchel","thunder bluff"},rel={"quest:5722","npc:maur-grimtotem","npc:rahauro","zone:ragefire","zone:thunderbluff","subzone:elder-rise","topic:tauren","topic:trogg"},m={start="Maur Grimtotem",["end"]="Rahauro",level="16",faction="Horde",id=5724},src={"Returning the Lost Satchel"}}
E["quest:5725"] = {t="quest",n="The Power to Destroy...",z="ragefire",s="Assigned by the dreadlord Varimathras in the Undercity, this task sends Horde adventurers deep into Ragefire Chasm beneath Orgrimmar. Lady Sylvanas Windrunner seeks two dark tomes possessed by the demonic Searing Blade cult to fuel her long-term war against the Scourge and the Lich King.",h="Assigned by the dreadlord Varimathras in the Undercity, this task sends Horde adventurers deep into Ragefire...",sec={{t="A Borrowed Arsenal",b="While Thrall's orcs focus on eradicating the Searing Blade cultists lurking directly under their capital, the Forsaken see an opportunity in the cult's occult stockpile. Varimathras, acting on Sylvanas Windrunner's orders, dispatches operatives to infiltrate Ragefire Chasm and seize two demonic grimoires: the Spells of Shadow and Incantations from the Nether. In the eyes of the Dark Lady, demonic gifts are far better utilized by disciplined Forsaken will than squandered by lesser cultists.",sp=0},{t="The War for Liberation",b="Upon securing the tomes, Varimathras reveals their broader purpose. The dark magic within is intended to empower Sylvanas's ongoing campaign against the Scourge. By claiming every scrap of forbidden power, the Forsaken hope to break the Lich King's grip across Lordaeron and completely liberate the remaining undead from his mental enslavement.",sp=0}},faq={{q="Why does Varimathras want books from underneath Orgrimmar?",a="The Searing Blade cultists inside Ragefire Chasm possess powerful demonic tomes. Lady Sylvanas believes these artifacts of the Burning Legion are wasted on mere cultists and wants their dark knowledge turned against the Lich King instead.",al={"why varimathras ragefire","undercity ragefire quest reason","why steal books"},it="motive"},{q="What books are you sent to collect?",a="You must claim two spellbooks from the Searing Blade cultists and warlocks: Spells of Shadow and Incantations from the Nether.",al={"what books","power to destroy books","ragefire book drops"},it="item"},{q="Where does Varimathras reside in the Undercity?",a="Varimathras stands beside Lady Sylvanas Windrunner in the Royal Quarter of the Undercity.",al={"varimathras location","where is varimathras","turn in location"},it="place"},{q="How does this relate to the Forsaken's overall goals?",a="Sylvanas is gathering every tool possible to wage war against the Scourge. Taking forbidden demonic arcana gives the Forsaken greater magical leverage to shatter the Lich King's dominion over the undead.",al={"forsaken motivation","why does sylvanas need spells","undercity lich king plot"},it="purpose"},{q="Does Thrall know the Forsaken are taking these books?",a="While the Horde leadership in Orgrimmar focuses on purging the traitors and demons from beneath their streets, Varimathras's specific retrieval order is framed as quiet business for the Dark Lady rather than an official joint Horde decree.",al={"does thrall know","orgrimmar undercity secret books","shadow council books orc reaction"},it="conflict"},{q="Who are the Searing Blade?",a="The Searing Blade is a secretive sect of the Shadow Council operating directly inside Ragefire Chasm beneath Orgrimmar, practicing dark demonic magic right under the Warchief's nose.",al={"what is searing blade","searing blade ragefire","ragefire cultists"},it="target"},{q="What are the Spells of Shadow and Incantations from the Nether?",a="These two tomes are dark grimoires gifted by the Burning Legion to their mortal worshipers. They contain powerful demonic lore and shadow magic that the Searing Blade cultists use to advance their masters' agenda. Lady Sylvanas believes such power is wasted on lesser pawns and intends to claim the grimoires to bolster the Forsaken's struggle against the Lich King.",al={"spells of shadow book","incantations from the nether","what are the books for"},it="item",add=true},{q="Why does Varimathras send you instead of the Royal Guard?",a="Varimathras has a hundred other tasks awaiting his attention, and the Searing Blade hide in caverns far away beneath Orgrimmar. Lady Sylvanas wants the cult's two spellbooks \"borrowed\" for her own ends, so Varimathras sends an ambitious adventurer to take them, promising further tasks to those who serve the Dark Lady well.",al={"why send me","why not royal guard","why doesnt varimathras go"},it="why_me",add=true}},ang={["race:Undead"]="For Forsaken champions, traveling across the Great Sea to plunder Orgrimmar's underbelly serves both their alliance with the Horde and the Dark Lady's ultimate ambition to destroy the Scourge.",["class:Warlock"]="Retrieving the Spells of Shadow and Incantations from the Nether represents a familiar study in wresting dangerous Legion arcana away from reckless cultists.",["faction:Horde"]="Clearing the Searing Blade helps secure the foundations of Orgrimmar, even if the magical spoils are whisked away to the Undercity's vaults."},kw={"incantations from the nether","lich king","ragefire chasm","searing blade","spells of shadow","sylvanas","undercity","varimathras"},rel={"npc:varimathras","zone:ragefire","zone:undercity","topic:forsaken","topic:shadow-council","topic:scourge","topic:lich-king","zone:orgrimmar"},m={start="Varimathras",level="16",faction="Horde",id=5725,ri={"Incantations from the Nether","Spells of Shadow"}},src={"The Power to Destroy... (Classic)"}}
E["quest:5728"] = {t="quest",n="Hidden Enemies",z="ragefire",s="Hidden Enemies is a pivotal infiltration task assigned by Warchief Thrall to eliminate the insidious cult flourishing beneath Orgrimmar. Having tricked the treacherous Neeru Fireblade into thinking you are an ally, Thrall sends you into the molten depths of Ragefire Chasm to assassinate the Searing Blade's top commanders.",h="Hidden Enemies is a pivotal infiltration task assigned by Warchief Thrall to eliminate the insidious cult...",sec={{t="A Cancer Beneath the Streets",b="Orgrimmar was built as a haven for a free Orcish race, yet its very foundations harbor old demonic shackles. Beneath the bustling markets lies the Cleft of Shadow, leading further down into the subterranean tunnels of Ragefire Chasm. Within these volcanic depths, remnants of the Shadow Council known as the Searing Blade gather strength, practicing dark arts and scheming to usurp the young Horde from within its own capital.",sp=0},{t="Playing the Double Agent",b="Direct assault without intelligence would leave the Shadow Council's network intact. Thrall orchestrated an undercover gambit, using you to bait out information from Neeru Fireblade, a seemingly cooperative warlock in the Cleft of Shadow. Convinced of your loyalty to their twisted cause, Neeru unwittingly surrendered the names of the cult's underground leadership: the corrupt satyr Bazzalan and the warlock Jergosh the Invoker.",sp=1},{t="Decapitating the Searing Blade",b="Thrall tasks you with descending into Ragefire Chasm to butcher Bazzalan and Jergosh, plunging the cultists into chaos. Crucially, the hits must remain deniable—Neeru cannot discover who carried out the slaughter, as Thrall intends to keep the warlock under watchful observation. Eliminating these ringleaders sends shockwaves through the cult, buying precious breathing room for the Horde's fledgling city.",sp=2}},faq={{q="Who orders the hit in Hidden Enemies?",a="Warchief Thrall directly commands this mission from the Valley of Wisdom in Orgrimmar, choosing to trust you with sensitive espionage to secure the city's underbelly.",al={"who gives hidden enemies","hidden enemies quest giver","thrall ragefire quest"},it="leader"},{q="Why doesn't Thrall just execute Neeru Fireblade?",a="Thrall prefers keeping Neeru alive under surveillance. Knowing who the traitor is allows the Warchief's scouts to monitor the Shadow Council's communications and anticipate future plots rather than letting a hidden replacement take his place.",al={"why not kill neeru","why keep neeru alive","neeru fireblade traitor"},sp=1},{q="Where are Bazzalan and Jergosh the Invoker located?",a="Both leaders reside deep within Ragefire Chasm, the dungeon accessible through the Cleft of Shadow in Orgrimmar. Jergosh occupies a volcanic ledge commanding the cultists, while the satyr Bazzalan lurks in an elevated cavern nearby.",al={"where is bazzalan","where is jergosh","ragefire chasm bosses"},it="place",gp=true},{q="Who are the Searing Blade?",a="The Searing Blade is a local sect aligned with the Burning Blade and Shadow Council. They worship demonic powers, practicing fel magic beneath Orgrimmar with the ultimate goal of overthrowing Thrall and enslaving the Horde anew.",al={"what is searing blade","searing blade cult","burning blade orgrimmar"},it="threat"},{q="Why is a satyr like Bazzalan working beneath an Orc city?",a="Satyrs are ancient servants of the Burning Legion. Bazzalan serves as a demonic handler and instigator, guiding the mortal cultists of the Searing Blade to execute the Legion's will directly under Thrall's feet.",al={"why is there a satyr in orgrimmar","bazzalan lore","satyr in ragefire"},it="origin"},{q="How does this quest fit into the broader Ragefire Chasm run?",a="Hidden Enemies is the climax of Thrall's infiltration chain. It aligns with multiple other dungeon quests targeting Ragefire Chasm, directing players to execute the dungeon's primary humanoid bosses in a single coordinated strike.",al={"is hidden enemies ragefire","rfc quest line","hidden enemies chain"},gp=true},{q="Why does Thrall want this done?",a="The Shadow Council seeks to seize Orgrimmar and tear the Horde from Thrall's grasp. Having learned from Neeru Fireblade that the Searing Blade operates right beneath the city's streets, Thrall recognizes their leaders as an imminent danger. Striking down Bazzalan and Jergosh deals an immediate blow to the cult's underground operations and throws their plotting into disarray before they can strike Orgrimmar from below.",al={"why does thrall want bazzalan dead","thrall motive hidden enemies","why kill searing blade leaders"},it="motive",add=true},{q="Who are you being sent to kill?",a="You are sent to eliminate Bazzalan and Jergosh the Invoker, the leaders of the Searing Blade cult nested deep within Ragefire Chasm. Bazzalan is a satyr commanding dark forces from the shadows, while Jergosh is a powerful warlock directing cult rituals. Both answer to Neeru Fireblade and serve as the cult's operational backbone in the caverns under Orgrimmar.",al={"who are the targets","who to kill hidden enemies","bazzalan and jergosh"},it="target",add=true},{q="Why does Thrall send you instead of the city guards?",a="Sending an army of Orgrimmar guards into the chasm would expose the warchief's awareness of the conspiracy and immediately blow your cover. Because you successfully infiltrated the Burning Blade and earned Neeru Fireblade's trust, you can slip down into Ragefire Chasm quietly. Thrall needs the leaders eliminated without Neeru discovering that his supposed recruit was the assassin, preserving your identity for future intelligence.",al={"why send me","why not use orgrimmar guards","why not send kor'kron"},it="why_me",add=true}},ang={["faction:Horde"]="Demonic corruption within the heart of Durotar threatens everything the new Horde fought to establish; cleansing Ragefire Chasm is vital to preserving their hard-won autonomy.",["race:Orc"]="For orcs seeking redemption from the blood-haze, eradicating the Shadow Council's remnants beneath Orgrimmar is a matter of profound cultural survival and honor.",["class:Warlock"]="While Thrall tolerates warlocks practicing dark arts for the defense of the Horde, Jergosh and the Searing Blade cross into treasonous servitude of demonic masters."},kw={"bazzalan","cleft of shadow","hidden enemies","jergosh the invoker","neeru fireblade","ragefire chasm","searing blade","shadow council","thrall"},rel={"npc:thrall","quest:5726","zone:ragefire","quest:829","npc:bazzalan","npc:jergosh-the-invoker","topic:shadow-council","subzone:cleft-of-shadow"},m={start="Thrall",level="16",faction="Horde",id=5728},src={"Hidden Enemies (3)"}}
E["quest:5761"] = {t="quest",n="Slaying the Beast",z="ragefire",s="Neeru Fireblade, an orc warlock residing in Orgrimmar's Cleft of Shadows, directs Horde adventurers deep into Ragefire Chasm to hunt Taragaman the Hungerer. Claiming to act on orders from Warchief Thrall, Neeru demands the towering felguard's heart as proof of the demonic cult's downfall.",h="Neeru Fireblade, an orc warlock residing in Orgrimmar's Cleft of Shadows, directs Horde adventurers deep into...",sec={{t="A Threat Beneath the City",b="Beneath the red earthen streets of Orgrimmar sits Ragefire Chasm, a fiery subterranean fissure infested with troggs, beasts, and the covert agents of the Searing Blade. In the Cleft of Shadows above, Neeru Fireblade presents himself as a loyal servant tasked by Thrall with cleansing this demonic rot. He points directly toward Taragaman the Hungerer, a massive felguard stationed in the heart of the cavern, naming the demon as the mastermind behind the underground cult.",sp=0},{t="The Warlock's Deception",b="Bringing Taragaman's heart back to Neeru Fireblade earns high praise and promises that Thrall will be appeased. In truth, Taragaman is not the genuine leader of the cult, but an expendable brute. By pointing Horde heroes at the demon, Neeru provides Thrall with a conspicuous victory to quiet suspicions while shielding the Searing Blade's actual leadership and deeper operations under Orgrimmar from closer scrutiny.",sp=1}},faq={{q="Who is Taragaman the Hungerer?",a="Taragaman the Hungerer is a powerful felguard stationed on a rocky platform in the heart of Ragefire Chasm. Neeru Fireblade names him as the leader of the Searing Blade cultists nesting beneath Orgrimmar.",al={"who is taragaman","what is taragaman","taragaman lore"},it="target"},{q="Who gives the quest Slaying the Beast?",a="Neeru Fireblade offers the quest from his tent in the Cleft of Shadows, the cavernous warlock quarter of Orgrimmar.",al={"quest giver slaying the beast","who gives this quest","neeru fireblade quest"},it="identity"},{q="Why does Neeru want Taragaman's heart?",a="Neeru claims the heart is needed to prove to Warchief Thrall that the demonic threat beneath Orgrimmar has been destroyed.",al={"why get the heart","taragaman heart purpose","why does neeru want the heart"},sp=1,it="item"},{q="Is Taragaman actually the leader of the Searing Blade?",a="Neeru Fireblade names him as their leader. Taragaman is a formidable felguard who dwells among the Searing Blade cultists in the heart of Ragefire Chasm.",al={"is taragaman the real leader","who leads searing blade","taragaman leader"},sp=1,it="threat"},{q="Where is Taragaman located?",a="Taragaman the Hungerer stands on a rock platform encircled by lava in the middle reaches of Ragefire Chasm, surrounded by Searing Blade cultists.",al={"taragaman location","where is the beast","where to find taragaman"},it="place",gp=true},{q="How does this quest connect to Hidden Enemies?",a="In the Hidden Enemies questline, Thrall investigates the Shadow Council's infiltration of Orgrimmar and keeps a watchful eye on Neeru Fireblade. Neeru offers this quest to show Thrall visible results against the Searing Blade.",al={"connection to hidden enemies","hidden enemies questline","thrall and neeru"},sp=1,it="ties"},{q="Why does Neeru Fireblade want Taragaman slain?",a="Neeru claims he is serving Warchief Thrall by rooting out the demonic corruption festering beneath Orgrimmar. By pointing you toward Taragaman the Hungerer and claiming the brute is the leader of the Searing Blade, Neeru provides Thrall with a prominent scapegoat. Slaying the demon offers the Warchief a visible victory while drawing suspicion far away from Neeru's own dark intrigues.",al={"why does neeru want this done","neeru fireblade motive","slaying the beast reason"},sp=1,it="motive",add=true}},ang={["class:Warlock"]="Operating out of the Cleft of Shadows alongside Neeru, warlocks see firsthand the political tightrope of practicing fel magic under Thrall's vigilant gaze.",["faction:Horde"]="Clearing the demonic presence festering directly under the Horde's capital is a matter of immediate civic survival for every race in Orgrimmar.",["race:Orc"]="For orcs striving to shake off the legacy of the demon blood curse, finding a felguard and demon cult nestled directly beneath Thrall's throne is an intolerable disgrace."},kw={"cleft of shadows","felguard","neeru fireblade","orgrimmar","ragefire chasm","searing blade","slaying the beast","taragaman"},rel={"npc:taragaman-the-hungerer","quest:829","zone:ragefire","quest:5726","zone:orgrimmar","npc:thrall","topic:horde"},m={start="Neeru Fireblade",level="16",faction="Horde",id=5761,ri={"Taragaman the Hungerer's Heart"}},src={"Slaying the Beast (quest)"}}
E["zone:ragefire"] = {t="dungeon",n="Ragefire Chasm",z="ragefire",s="Ragefire Chasm is a network of winding volcanic tunnels situated directly beneath the orcish capital of Orgrimmar. Entered through the dark hollows of the Cleft of Shadow, the chasm is overrun by savage troggs and a demonic sect of cultists known as the Searing Blade. Left unchecked, the dark powers and subterranean swarms festering below threaten the very foundation of the young Horde nation.",h="Ragefire Chasm is a network of winding volcanic tunnels situated directly beneath the orcish capital of...",sec={{t="Subterranean Peril",b="Beneath the dust and red rocks of Orgrimmar lies a blistering maze of volcanic corridors and lava pits. While orcish builders forged their new home above, aggressive Ragefire troggs began erupting from deep below the surface. Magatha Grimtotem sought to open diplomatic channels with the brutes on behalf of Thunder Bluff, but her envoy Maur Grimtotem was slaughtered, proving the troggs will yield only to force.",sp=0},{t="The Searing Blade",b="Far more dangerous than simple troggs is the presence of the Searing Blade, a fanatical cell loyal to the Shadow Council. Operating from the dark caverns alongside the magma streams, this demonic cult plots the utter ruin of the fledgling Horde. They are led by the warlock Jergosh the Invoker, a cunning satyr named Bazzalan, and the vicious felguard Taragaman the Hungerer, who presides over an altar in the lava lake.",sp=0},{t="The Warchief's Game",b="Neeru Fireblade, an ostensible warlock trainer dwelling beside the chasm's entrance in the Cleft of Shadow, secretly serves as the local leader of the Burning Blade. Neeru sends Horde adventurers into the depths under the guise of loyalty tests, hoping to cull weak cultists and eliminate Thrall's supporters. However, Thrall is fully aware of Neeru's deception. The Warchief uses these forays to eliminate dangerous cult leaders like Jergosh and Bazzalan while letting Neeru remain in place to monitor the Shadow Council's broader schemes.",sp=1}},faq={{q="Where is the entrance to Ragefire Chasm?",a="The entrance portal is located inside Orgrimmar within the subterranean district known as the Cleft of Shadow. It sits near the tent of the warlock trainer Neeru Fireblade.",al={"rfc location","where is rfc","ragefire entrance"},it="place",gp=true},{q="Why are troggs under Orgrimmar?",a="The Ragefire troggs tunneled upward from subterranean recesses beneath Durotar. Their sudden presence beneath the capital is regarded as a severe danger that diplomacy failed to quell.",al={"ragefire troggs origin","why are there troggs here","orgrimmar troggs"},it="threat"},{q="Who leads the cultists inside the chasm?",a="The Searing Blade within the chasm is directed by the warlock Jergosh the Invoker and the satyr Bazzalan, both supported by the summoned felguard Taragaman the Hungerer.",al={"rfc bosses","searing blade leaders","who rules ragefire"},it="threat"},{q="What does killing Bazzalan and Jergosh accomplish for the story?",a="Slaying Bazzalan and Jergosh breaks the active leadership of the Searing Blade cultists lurking under Orgrimmar. Their deaths demonstrate the Horde's resilience and allow Thrall to thwart a demon-worshiping cell right beneath his throne.",al={"bazzalan lore meaning","why kill bazzalan","hidden enemies outcome"},sp=1,it="purpose"},{q="Can Alliance adventurers enter Ragefire Chasm?",a="Physically, any adventurer can walk through the portal, but reaching the Cleft of Shadow deep inside Orgrimmar as an Alliance member requires evading high-level Horde guards and hostile defenders throughout the city.",al={"can alliance do rfc","alliance in ragefire"},gp=true},{q="Why doesn't Thrall simply execute Neeru Fireblade?",a="Thrall tolerates the practitioners of dark magic who gather in the Cleft of Shadow, preferring to keep them close and under his watchful eye rather than drive them out of sight.",al={"thrall neeru fireblade","why let neeru live"},sp=1,it="motive"},{q="What is Ragefire Chasm?",a="Ragefire Chasm is a subterranean network of fiery volcanic caverns running directly beneath the orc capital city of Orgrimmar. While it sits just under the bustling streets above, its molten depths harbor vicious troggs and a hidden cabal of Searing Blade cultists plotting against the Horde.",al={"what is ragefire chasm","about ragefire chasm","rfc lore"},it="place",add=true},{q="Why is there a cave under Orgrimmar?",a="The caverns naturally formed as a volcanic network within the rocky earth beneath Durotar. When the orcs chose this defensible canyon to construct Orgrimmar, the fiery chasm already lay beneath the ground, hollowed out by ancient subterranean magma flows.",al={"why cave under orgrimmar","how did ragefire chasm form","caves beneath orgrimmar"},it="place",add=true,nx={9}},{q="Did the orcs dig it out?",a="No. The orcs did not excavate Ragefire Chasm. It was already a natural labyrinth of molten stone and lava vents long before Thrall led his people to settle in Durotar and raise the walls of Orgrimmar above it.",al={"did orcs dig rfc","did the horde dig ragefire chasm"},it="origin",add=true},{q="Why did Thrall send me down here?",a="Thrall uncovered whispers of cultist activity festering right beneath his city. Rather than launching an overt military raid that would alert the traitors, he dispatched promising adventurers into the depths to investigate the threat and eliminate the Searing Blade's shadowy leaders.",al={"why thrall sent me rfc","thrall ragefire quest reason","why am i in ragefire chasm"},it="purpose",add=true},{q="Who is Thrall?",a="Thrall is the Warchief of the Horde and founder of the nation of Durotar. Born Go'el to Chieftain Durotan of the Frostwolf clan, he escaped human servitude and gladiator pits to unite the shattered orc clans, reviving their forgotten shamanic heritage and forging a new, honorable Horde.",al={"who is warchief thrall","thrall lore","who is thrall"},it="in_charge",add=true,nx={12,13}},{q="How did he become Warchief?",a="Thrall fought alongside Orgrim Doomhammer to liberate imprisoned orcs from Alliance internment camps after the Second War. When Doomhammer fell in battle, he bequeathed his legendary black armor and warhammer to Thrall, naming him the new Warchief to lead their people to Kalimdor.",al={"how thrall became warchief","thrall leadership origin","how did thrall get doomhammer"},it="history",add=true},{q="Is Thrall a shaman?",a="Yes. Guided by the spirits and the ancient hermit Drek'Thar of the Frostwolf clan, Thrall became the first new orc shaman in a generation, rejecting the corrupting demonic fel magic that had once enslaved his race in favor of harmony with the elements.",al={"is thrall shaman","thrall class","can thrall use magic"},it="identity",add=true},{q="What are the Hidden Enemies Thrall is talking about?",a="The Hidden Enemies are demonic cultists and sympathizers who dwell secretly within Durotar, plotting to overthrow Thrall's fledgling society. Operating from shadows and hidden tunnels, they serve dark powers from the orcs' past and actively undermine the Horde's peace from within.",al={"hidden enemies thrall","who are hidden enemies","what are hidden enemies"},it="threat",add=true},{q="Why are there demons under Orgrimmar?",a="The cultists of the Searing Blade brought demons like Taragaman the Hungerer into the depths to anchor their dark rituals. Lurking beneath the Cleft of Shadow, they use demonic power to lure unwary citizens and test initiates who wish to serve the Burning Legion.",al={"demons in ragefire chasm","why demons under orgrimmar","taragaman in rfc"},it="threat",add=true},{q="What is the Shadow Council?",a="The Shadow Council was a secretive cabal of warlocks originally formed on Draenor by Gul'dan to manipulate the orc clans and bind them to the Burning Legion. Though shattered during the First and Second Wars, lingering sects like the Burning Blade continue working toward their demonic masters' goals.",al={"shadow council lore","whats the shadow council","shadow council history"},it="history",add=true},{q="What are the Ragefire troggs?",a="The Ragefire troggs are a violent, subterranean clan of primitive troggs infesting the upper reaches of the chasm. Barbaric and aggressive, they burst into the caverns from subterranean fissures, immediately attacking anyone who enters their territory.",al={"ragefire troggs","what are the troggs in rfc","rfc troggs"},it="threat",add=true},{q="Why me, I'm not exactly a hero yet?",a="Thrall cannot deploy his elite Kor'kron guards without alarming the conspirators and driving them deeper underground. By employing eager new adventurers, he mounts a quiet, deniable strike that eliminates the cult's immediate lieutenants while keeping his own counter-investigations discreet.",al={"why send me rfc","why adventurer for ragefire","why me ragefire"},it="why_me",add=true},{q="What happens after I kill the warlock and the satyr?",a="Once Jergosh the Invoker and Bazzalan fall, their plans inside the chasm are crippled. You report your triumph back to Thrall, who confirms the existence of a larger web of betrayal that reaches beyond the caverns into the surface world.",al={"after killing bazzalan jergosh","slay jergosh next step","what to do after rfc"},sp=1,it="next_step",add=true,nx={20}},{q="Does this lead back to Thrall?",a="Yes. Thrall expects you to report directly to his throne room in the Valley of Wisdom. Slaying the cult's field masters proves your loyalty and informs the Warchief of the true scope of the subversion brewing right under his feet.",al={"does rfc lead back to thrall","return to thrall after rfc","report to thrall"},sp=1,it="next_step",add=true},{q="How did I end up in Ragefire Chasm?",a="You descended through the shadowy tunnels beneath Orgrimmar into the Cleft of Shadow, where the city's outcasts and darker practitioners gather. Beside the tent of the warlock Neeru Fireblade lies the cleft's deepest threshold: a smoking archway that plunges straight into the volcanic underbelly of Durotar. Whether directed here by Warchief Thrall to hunt down hidden traitors, sent by tauren emissaries from Thunder Bluff, or steered below by dark whisperers testing your mettle, you walked through that gateway into the subterranean magma tunnels.",al={"how did i get here","how did i get to ragefire chasm","why am i in these caverns"},it="arrival",add=true},{q="What am I supposed to be doing in Ragefire Chasm?",a="You are here to purge a festering rot threatening the heart of the Horde. In these volcanic caverns, feral troggs have clawed up from the depths, violently rejecting peace and slaughtering emissaries. Worse still, the Searing Blade—a covert splinter of the demonic Shadow Council—plots Orgrimmar's ruin from the dark. Your duty is to cut through the troggs, confront the hulking felguard Taragaman the Hungerer, and eliminate the cult's mortal commanders, Jergosh the Invoker and the satyr Bazzalan, shattering their subterranean network before it overruns the city above.",al={"what am i doing here","what is my goal in ragefire","why was i sent down here"},it="purpose",add=true}},ang={["faction:Horde"]="Cleansing the chasm under Orgrimmar is an essential trial for young champions to prove their strength and protect the Horde's vulnerable capital.",["class:Warlock"]="The dark rites and demonic tomes used by Jergosh the Invoker and Bazzalan offer warlock initiates a firsthand look at the dark magic of the Searing Blade.",["race:Tauren"]="Maur Grimtotem's tragic death at the hands of the Ragefire troggs makes hunting the subterranean beasts a matter of honor and retribution for Thunder Bluff."},kw={"bazzalan","chasm","cleft of shadow","jergosh","neeru fireblade","orgrimmar","ragefire","rfc","searing blade","taragaman"},rel={"npc:thrall","zone:orgrimmar","subzone:cleft-of-shadow","npc:taragaman-the-hungerer","npc:jergosh-the-invoker","npc:bazzalan","quest:5726","npc:magatha-grimtotem"},m={levels="13-18"},src={"Ragefire Chasm (Classic)","Ragefire Chasm"}}
